// AuthConfig Authentication + SSO configuration. Persisted under the
// sysconfig key `auth`. The password policy applies only to
// local accounts; SSO logins are validated by the upstream
// identity provider. SSO providers are STORED here but not yet
// USED at login time — enforcement lands in a follow-up phase.
type AuthConfig struct {
	PasswordPolicy struct {
		// DisallowCommon Reject common-password list ("password", "123456", ...).
		DisallowCommon bool `json:"disallow_common"`

		// MaxAgeDays 0 = passwords never expire.
		MaxAgeDays    int  `json:"max_age_days"`
		MinLength     int  `json:"min_length"`
		RequireNumber bool `json:"require_number"`
		RequireSymbol bool `json:"require_symbol"`
		RequireUpper  bool `json:"require_upper"`
	} `json:"password_policy"`

	// SelfRegistration Self-service signup tunables. Default
	// zero-valued (disabled, verification on, role "Base") so
	// installs upgrading without opting in stay closed.
	SelfRegistration *struct {
		// DefaultRole Role name assigned to fresh signups. Default "Base".
		// Operators can point this at a more restricted role
		// for moderated communities.
		DefaultRole *string `json:"default_role,omitempty"`

		// Enabled Master switch. /auth/register returns 403 when false.
		Enabled *bool `json:"enabled,omitempty"`

		// RequireEmailVerification When true (recommended), new accounts must click a
		// verification link before they can sign in. Disable
		// only for closed-network installs where outbound
		// SMTP isn't available.
		RequireEmailVerification *bool `json:"require_email_verification,omitempty"`
	} `json:"self_registration,omitempty"`
	SsoProviders []struct {
		// Config Per-kind configuration for one SSO provider. Every field is
		// optional and which subset applies is decided by the provider's
		// `kind` — OAuth fields for `google`/`github`/`x`, the LDAP block
		// for `ldap`, the SAML block for `saml`.
		//
		// This schema is CLOSED (`additionalProperties: false`) on
		// purpose (#718). It used to be a free-form map, which meant the
		// read path handed every stored bind password, client secret and
		// SP private key to anyone holding `system.config.read`. Naming
		// each field is what lets the three secrets be marked write-only;
		// a free-form remainder would put the leak straight back, because
		// the server cannot know which unknown key holds a credential.
		//
		// Nothing consumes these values at login time yet — SSO
		// enforcement lands in a later phase. The names follow the
		// upstream protocol vocabulary (RFC 6749 for OAuth, RFC 4511 for
		// LDAP, SAML 2.0 core/bindings) so the integration code inherits
		// them rather than renaming them.
		Config      *SSOProviderConfig `json:"config,omitempty"`
		DisplayName string             `json:"display_name"`
		Enabled     bool               `json:"enabled"`

		// Id Stable identifier assigned by the admin UI on create.
		// Empty on a freshly-added provider; the handler fills
		// it in. Used as OAuth `state` and as the row key for
		// later edits.
		Id   *string                    `json:"id,omitempty"`
		Kind AuthConfigSsoProvidersKind `json:"kind"`
	} `json:"sso_providers"`
}

